#!/usr/bin/env node
// ADR 0214 review H4: generate ctrl's secure-word lists (Rust host + Swift helper) from spec/ctrl/secure-words.json.
// Usage: node scripts/ctrl/gen-secure-words.mjs [--check]   (--check: exit 1 if a generated file is stale)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../..',
);
const spec = JSON.parse(
  fs.readFileSync(path.join(root, 'spec/ctrl/secure-words.json'), 'utf8'),
);
const q = (s) => JSON.stringify(s);
const rust = `// @generated by scripts/ctrl/gen-secure-words.mjs from spec/ctrl/secure-words.json. Do not edit.
/// Words that make a text input a password, identity or payment field: excluded from the tree entirely.
pub const SENSITIVE_WORDS: &[&str] = &[${spec.words.map(q).join(', ')}];
/// Two-word phrases that do the same.
pub const SENSITIVE_PHRASES: &[(&str, &str)] = &[${spec.phrases.map(([a, b]) => `(${q(a)}, ${q(b)})`).join(', ')}];
`;
const swift = `// @generated by scripts/ctrl/gen-secure-words.mjs from spec/ctrl/secure-words.json. Do not edit.
public enum CtrlSecureWords {
    public static let words: Set<String> = [${spec.words.map(q).join(', ')}]
    public static let phrases: [(String, String)] = [${spec.phrases.map(([a, b]) => `(${q(a)}, ${q(b)})`).join(', ')}]
}
`;
const out = [
  ['crates/qrtz-ctrl/src/secure_words.rs', rust],
  ['native/qrtz-helper/Sources/QrtzCtrl/CtrlSecureWords.swift', swift],
];
let stale = false;
for (const [f, s] of out) {
  const p = path.join(root, f);
  const cur = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : '';
  if (cur === s) continue;
  if (process.argv.includes('--check')) {
    console.error(`${f} is stale: node scripts/ctrl/gen-secure-words.mjs`);
    stale = true;
  } else fs.writeFileSync(p, s);
}
process.exit(stale ? 1 : 0);
